`timescale 1ns/1ns
package tick_pkg;
  task automatic tick(output int r);
    static int n = 0;
    #1;
    n++;
    r = n;
  endtask
endpackage
module Top;
  import tick_pkg::*;
  class Counter #(int STEP = 1);
    static task bump(output int r);
      static int n = 0;
      #1;
      n += STEP;
      r = n;
    endtask
  endclass
  int a, b, c1, c2;
  initial tick(a);
  initial tick_pkg::tick(b);
  initial Counter#(1)::bump(c1);
  initial Counter#(1)::bump(c2);
  initial #5 $display("a+b=%0d c1+c2=%0d", a + b, c1 + c2);
endmodule
